int mlx4_register_mac(struct mlx4_dev *dev, u8 port, u64 mac, int *index)
{
        int err = -ENOSPC;
        int i;

        mutex_lock(&dev->mac_table.mutex);

        for (i = 0; i < dev->mac_table.max_num_macs; ++i) {
                struct mlx4_mac_table_entry *entry = &dev->mac_table.entry[i];

                if (entry->ref_count && entry->mac == mac) {
                        (*index) = i;
                        entry->ref_count++;
                        err = 0;
                        goto out;
                }
        }

        for (i = 0; i < dev->mac_table.max_num_macs; ++i) {
                struct mlx4_mac_table_entry *entry = &dev->mac_table.entry[i];

                if (!entry->ref_count) {
                        entry->mac = mac;
                        entry->ref_count = 1;
                        (*index) = i;
                        err = mlx4_PORT_set_mac(dev, port, mac);
                        if (err)
                                goto out;
                        else {
                                err = 0;
                                goto out;
                        }
                }
        }

out:
        mutex_unlock(&dev->mac_table.mutex);
        return err;
}

int mlx4_register_mac_address(struct mlx4_dev *dev, u8 port, u64 mac, int *index)
{
	int i, err = 0;
	struct mlx4_mac_table *mac_table = &dev->mac_table[port - 1];
	unsigned long flags;

	spin_lock_irqsave(&mac_table->lock, flags);

	/* Check if MAC is already registered */
	for (i = 0; i < mac_table->size; ++i) {
		if (mac_table->macs[i] == mac) {
			mac_table->ref_count[i]++;
			*index = i;
			goto out;
		}
	}

	/* Find a free entry */
	for (i = 0; i < mac_table->size; ++i) {
		if (mac_table->macs[i] == 0) {
			mac_table->macs[i] = mac;
			mac_table->ref_count[i] = 1;
			*index = i;
			err = mlx4_WRITE_MAC_address(dev, port, i, mac);
			if (err) {
				mac_table->macs[i] = 0;
				mac_table->ref_count[i] = 0;
			}
			goto out;
		}
	}

	/* No free entries */
	err = -ENOSPC;
	goto out;

out:
	spin_unlock_irqrestore(&mac_table->lock, flags);
	return err;
}

int register_mac_address(struct mlx4_dev *dev, u8 port, u64 mac, int *index)
{
        int i, err = -ENOSPC;

        mutex_lock(&dev->mac_table_mutex);

        for (i = 0; i < MLX4_MAX_MAC_ADDRS; i++) {
                if (dev->mac_table[port - 1][i].mac == mac) {
                        dev->mac_table[port - 1][i].ref_count++;
                        *index = i;
                        err = 0;
                        goto out;
                }
        }

        for (i = 0; i < MLX4_MAX_MAC_ADDRS; i++) {
                if (!dev->mac_table[port - 1][i].ref_count) {
                        dev->mac_table[port - 1][i].mac = mac;
                        dev->mac_table[port - 1][i].ref_count = 1;
                        *index = i;
                        err = 0;
                        break;
                }
        }

        if (err)
                goto out;

        err = mlx4_register_mac(dev, port, mac);

out:
        mutex_unlock(&dev->mac_table_mutex);
        return err;
}

int mlx4_register_mac(struct mlx4_dev *dev, u8 port, u64 mac, int *index)
{
	int err = -ENOSPC;
	int i;

	mutex_lock(&dev->mac_table.mutex);

	/* Check if MAC is already registered */
	for (i = 0; i < dev->mac_table.size; ++i) {
		if (dev->mac_table.entries[i].port == port &&
		    dev->mac_table.entries[i].mac == mac) {
			/* MAC already exists, increment ref count */
			dev->mac_table.entries[i].ref_count++;
			*index = i;
			mutex_unlock(&dev->mac_table.mutex);
			return 0;
		}
	}

	/* Find a free entry */
	for (i = 0; i < dev->mac_table.size; ++i) {
		if (!dev->mac_table.entries[i].ref_count) {
			/* Register new MAC */
			dev->mac_table.entries[i].port = port;
			dev->mac_table.entries[i].mac = mac;
			dev->mac_table.entries[i].ref_count = 1;
			*index = i;

			err = mlx4_WRITE_MAC_ADDR(dev, port, mac);
			if (err) {
				dev->mac_table.entries[i].port = 0;
				dev->mac_table.entries[i].mac = 0;
				dev->mac_table.entries[i].ref_count = 0;
			} else {
				mutex_unlock(&dev->mac_table.mutex);
				return 0;
			}
			break;
		}
	}

	mutex_unlock(&dev->mac_table.mutex);
	return err;
}

int mlx4_register_mac_address(struct mlx4_dev *dev, u8 port, u64 mac, int *index)
{
        int i, err = -ENOSPC;

        mutex_lock(&dev->mac_table.mutex);

        for (i = 0; i < MLX4_MAC_NUM; ++i) {
                struct mlx4_mac_entry *entry = &dev->mac_table.entry[i];

                if (entry->port == port && entry->mac == mac) {
                        ++entry->ref_count;
                        *index = i;
                        err = 0;
                        goto out;
                }

                if (!entry->ref_count) {
                        err = mlx4_cmd(dev, (mac << 8) | port, i, MLX4_CMD_REGISTER_MAC,
                                         MLX4_CMD_TIME_CLASS_A, MLX4_CMD_NATIVE);
                        if (!err) {
                                entry->port    = port;
                                entry->mac     = mac;
                                entry->ref_count = 1;
                                *index = i;
                                goto out;
                        }
                }
        }

out:
        mutex_unlock(&dev->mac_table.mutex);
        return err;
}
